import React, { forwardRef, PropsWithChildren } from "react";
import clsx from "clsx";
import { Link as LinkStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps, LinkTarget } from "../helperTypes";

type Props = PropsWithChildren<{
  /** Disabled state */
  disabled?: boolean;
  /** url to traverse to */
  href?: string;
  /**
   * Apply inline link styling (to be used in paragraphs)
   * @default false
   */
  inline?: boolean;
  /**
   * Apply negative styling on dark backgrounds
   * This will change the color of the link to be more visible on dark backgrounds.
   * This is useful when the link is used in a dark themed component or page.
   * @default false
   */
  negative?: boolean;
  /** mouse click handler */
  onClick?: React.MouseEventHandler<HTMLAnchorElement>;
  /**
   * The size of the link
   * @default medium
   */
  size?: "xsmall" | "small" | "medium" | "large";
  /**
   * link target
   * @default _self
   */
  target?: LinkTarget;
  /** the title for the link */
  title?: string;
}>;

export type LinkProps = Props & CommonProps;

const useStyles = createUseStyles(LinkStyles, "link");

export const Link = (props: LinkProps, ref: React.Ref<HTMLAnchorElement>) => {
  const {
    children,
    className,
    disabled,
    inline,
    negative,
    onClick,
    size,
    target,
    title,
    ...rest
  } = props;
  const classes = useStyles();

  return (
    <a
      ref={ref}
      className={clsx(
        className,
        classes.root,
        inline && classes._inline,
        negative && classes._negative,
        size && classes[`_${size}`],
        disabled && classes._disabled
      )}
      onClick={disabled ? undefined : onClick}
      aria-disabled={disabled}
      aria-label={title}
      target={target}
      title={title}
      tabIndex={disabled ? -1 : undefined}
      {...rest}
    >
      {children}
    </a>
  );
};

export default forwardRef<HTMLAnchorElement, LinkProps>(Link);
